style.css:
/* RBX Snow - Roblox */
:root {
  /* Tu peux modifier ces couleurs */
  --my-bg: #f7f8fa;
  --my-card: #ffffff;
  --my-text: #24272d;
  --my-muted: #858b96;
  --my-border: #e9ebef;
  --my-accent: #dfe3e9;
}

/* fond et texte */
html,
body {
  background: var(--my-bg) !important;
  color: var(--my-text) !important;
  font-family: Arial, sans-serif !important;
}

/* liens */
a {
  color: var(--my-text) !important;
}

/* images */
img {
  border-radius: 12px !important;
}

/* barres de défilement */
::-webkit-scrollbar {
  width: 8px !important;
}

::-webkit-scrollbar-thumb {
  background: #d5d9df !important;
  border-radius: 20px !important;
}

/* champs de saisie */
input,
textarea {
  background: #fff !important;
  color: var(--my-text) !important;
  border: 1px solid var(--my-border) !important;
  border-radius: 10px !important;
}
